		go postgresServer.Serve()
		t.Cleanup(func() { postgresServer.Close() })
		server := types.NewDatabaseServerV3(name, nil,
			types.DatabaseServerSpecV3{
				Protocol:      defaults.ProtocolPostgres,
				URI:           net.JoinHostPort("localhost", postgresServer.Port()),
				Version:       teleport.Version,
				Hostname:      constants.APIDomain,
				HostID:        testCtx.hostID,
				DynamicLabels: dynamicLabels,
				AWS: types.AWS{
					Region: "us-east-1",
				},
				// Set CA cert, otherwise we will attempt to download RDS roots.
				CACert: testCtx.hostCA.GetTLSKeyPairs()[0].Cert,
			})
		_, err = testCtx.authClient.UpsertDatabaseServer(ctx, server)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	csr, err := tlsca.GenerateCertificateRequestPEM(subject, privateKeyBytes)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	response, err := s.cfg.AuthClient.SignDatabaseCSR(ctx, &proto.DatabaseCSRRequest{
		CSR:         csr,
		ClusterName: identity.RouteToCluster,
	})
	if err != nil {
		return nil, trace.Wrap(err)
	}
	cert, err := tls.X509KeyPair(response.Cert, privateKeyBytes)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	pool := x509.NewCertPool()
	for _, caCert := range response.CACerts {
		ok := pool.AppendCertsFromPEM(caCert)
		if !ok {
			return nil, trace.BadParameter("failed to append CA certificate")
		}
	}
	return &tls.Config{
		ServerName:   server.GetHostname(),
		Certificates: []tls.Certificate{cert},
		RootCAs:      pool,
	}, nil
}

